-- Queries for dynamic CEL policies. Defaults are seeded from Go code on
-- startup; the stored expression always wins. The primary key is a UUIDv7
-- generated by the application; name is the stable permission identifier.

-- name: CreatePolicy :one
INSERT INTO policies (id, name, expression)
VALUES (?, ?, ?)
RETURNING id, name, expression;

-- name: GetPolicyByName :one
SELECT id, name, expression
FROM policies
WHERE name = ?
LIMIT 1;

-- name: UpdatePolicyExpression :exec
UPDATE policies
SET expression = ?, updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
WHERE id = ?;

-- name: ListPolicies :many
SELECT id, name, expression
FROM policies
ORDER BY name;

-- name: CreatePolicyVersion :exec
INSERT INTO policy_versions (
    policy_id, expression, changed_by, changed_by_email, origin
)
VALUES (?, ?, ?, ?, ?);

-- name: ListPolicyVersions :many
SELECT v.expression, v.changed_by, v.changed_by_email, v.origin, v.created_at
FROM policy_versions v
JOIN policies p ON p.id = v.policy_id
WHERE p.name = ?
ORDER BY v.id DESC
LIMIT ?;
